function get_direction(probability = R.random_num(0.1,0.5)) {
    let random_int = R.random_num(0,1)
    let left_probability = 1 - probability
    let left = false;
	  let right = false;
    if (random_int >= left_probability) {
        left = true
		}
    else if (random_int <= probability) {
        left = true
		}

		else {
			left = true
			right = true

		}
    return createVector(left, right)

}

