function get_direction_1(probability = 0.1) {
   let random_int = R.random_num(0,1)
   let left_probability = 1 - probability
   let left = false;
     let right = false;
   if (R.random_num_int >= left_probability) {
       left = true
       }
   else if (R.random_num_int <= probability) {
       left = true
       }

       else {
           left = true
           right = true

       }
   return createVector(left, right)

}


