 let steps = R.random_num(1, 10);
 let theta = radians(a);
 h *= R.random_num(0.7, 1);// R.random_num(0.7, 1);
 let i = ghiloch_positions.length;
 ghiloch_positions[i] = createvector(ghiloch_positions[i-1].x + h*cos((theta)), ghiloch_positions[i-1].y - h*sin((theta)));

 if (ghiloch_positions[i].x > 0 && ghiloch_positions[i].y > 0) {
   if (h > threshold) {
     if (right5) {
       draw_ghiloch3(theta, h, threshold, first_thickness_kiloch5, ghiloch_positions);
     }
     if (left5) {
       draw_ghiloch3(-theta, h, threshold, first_thickness_kiloch5, ghiloch_positions);
     }
   } else {
     shapegraphic2.push();
     shapegraphic2.noStroke();
     shapegraphic2.pop();
   }
 }
}

function get_direction5(probability = R.random_num(0.1,0.6)) {
 let random_int = R.random_num(0,1);
 let left5_probability = 1 - probability;
 let left5 = false;
 let right5 = false;
 if (random_int >= left5_probability) {
   left5 = true;
 } else if (random_int <= probability) {
   left5 = true;
 } else {
   left5 = true;
   right5 = true;
 }
 return createVector(left5, right5);
}
